function lesson10Dialogue(){app.innerHTML=intro('HỘI THOẠI · BÀI 10','Đến nhà làm khách và thưởng thức bữa cơm.','Hai hội thoại được chép lại từ các trang bạn gửi.')+lesson2VoiceControls()+'<button class="btn secondary" id="pinyin">'+(showPinyin?'Ẩn':'Hiện')+' pinyin</button>'+lesson10Data.dialogues.map(([title,lines],d)=>'<h2>'+title+'</h2><button class="btn secondary" data-lesson10-full="'+d+'">▶ Nghe toàn hội thoại</button>'+lines.map(([name,zh,py,vi],i)=>'<article class="dialogue"><small>'+name+'</small><button class="text-button" data-lesson10-line="'+d+','+i+'" aria-label="Nghe câu '+(i+1)+'">▶</button><p class="han">'+zh+'</p>'+(showPinyin?'<p class="pinyin">'+py+'</p>':'')+'<p>'+vi+'</p></article>').join('')).join('')+lesson10References(5,8);bindLesson2Voice(lesson10Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelector('#pinyin').onclick=()=>{stopWordAudio();showPinyin=!showPinyin;lesson10Dialogue();};document.querySelectorAll('[data-lesson10-line]').forEach(b=>b.onclick=()=>{const[d,i]=b.dataset.lesson10Line.split(',').map(Number);lesson2Speak(lesson10Data.dialogues[d][1][i][1]);});document.querySelectorAll('[data-lesson10-full]').forEach(b=>b.onclick=()=>lesson2Speak(lesson10Data.dialogues[Number(b.dataset.lesson10Full)][1].map(l=>l[1]).join(' ')));}
function lesson10BTNCMarkup(file){const group=lesson10BTNC.find(g=>g.file===file);if(!group)return '<p class="sub">File chính Q2B10; xem phần đáp án BTNC trên trang tham khảo bên dưới.</p>'+lesson10BTNCReference();const id=lesson10BTNC.indexOf(group),saved=state.lesson10Exercises?.['btnc'+id]||{};return '<details class="lesson2-answer-key"><summary>Luyện nghe với 5 câu hỏi</summary><p class="sub">Câu hỏi tự luyện biên soạn từ bản ghi lời nghe, không phải bộ lựa chọn của đề BTNC gốc.</p><form id="lesson10BTNCForm'+id+'">'+group.questions.map((q,i)=>'<fieldset class="question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l10nc'+id+'q'+i+'" value="'+j+'" '+(String(saved[i]?.answer)===String(j)?'checked':'')+'> '+v+'</label>').join('')+'<div id="lesson10BTNCFeedback'+id+'-'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson10BTNCResult'+id+'" role="status"></p></form></details><details class="lesson2-answer-key"><summary>Bản ghi lời nghe và đáp án BTNC gốc</summary>'+group.transcript.map((t,i)=>'<p lang="zh-CN" style="white-space:pre-line">'+(i+1)+'. '+esc(t)+'</p>').join('')+'<p><b>Đáp án '+group.title+':</b> '+group.key.map((k,i)=>(i+1)+'. '+k).join(' · ')+'</p><p class="sub">Các chữ cái dùng đối chiếu với đề BTNC gốc; câu tự luyện phía trên có thứ tự lựa chọn riêng.</p>'+lesson10BTNCReference()+'</details>';}
function lesson10BTNCReference(){return '<details class="lesson2-reference"><summary>Xem trang đáp án BTNC bài 10</summary><img loading="lazy" style="max-width:100%;height:auto" src="images/lesson10/btnc-answers-page21.png" alt="Đáp án BTNC bài 10, trang 21 của PDF"></details>';}
function bindLesson10BTNC(){lesson10BTNC.forEach((group,id)=>{document.querySelector('#lesson10BTNCForm'+id).onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;group.questions.forEach((q,i)=>{const answer=form.get('l10nc'+id+'q'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson10BTNCFeedback'+id+'-'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson10Exercises=state.lesson10Exercises||{};state.lesson10Exercises['btnc'+id]=records;save();document.querySelector('#lesson10BTNCResult'+id).textContent='Đúng '+count+' / 5 câu.';};});}

