function lesson10References(first=1,last=12){return '<details class="lesson2-reference"><summary>Xem trang giáo trình gốc</summary>'+Array.from({length:last-first+1},(_,i)=>'<figure><img loading="lazy" src="images/lesson10/source-'+(first+i)+'.png" alt="Bài 10 · ảnh nguồn '+(first+i)+'"><figcaption>Trang '+lesson10SourcePages[first+i-1]+'</figcaption></figure>').join('')+'</details>';}
function lesson10Home(){app.innerHTML=intro('HSK2 · LESSON 10',lesson10Data.title,lesson10Data.pinyin+' · '+lesson10Data.vi)+'<section class="hero"><div><h2>Làm khách, trò chuyện và cảm ơn</h2><p>Chào hỏi chủ nhà, khen món ăn và diễn đạt lịch sự.</p><a class="btn" href="#words">Học 19 mục từ →</a></div><div class="hero-mark" aria-hidden="true">客</div></section><div class="stats"><div class="stat"><small>TỪ ĐÃ NHỚ</small><strong>'+state.known.length+'<small> / 19</small></strong></div><div class="stat"><small>HỘI THOẠI</small><strong>02</strong></div><div class="stat"><small>TRANG GIÁO TRÌNH</small><strong>117–128</strong></div></div><div class="grid">'+[['words','Từ vựng','Nghe & gõ · Flashcard · Ghép từ'],['grammar','Mẫu câu & ôn tập','Làm khách · 别 · 又……又……'],['dialogue','Hội thoại','Đến nhà cô Hoàng · Thưởng thức bữa cơm'],['practice','Luyện tập','Điền từ · Đọc hiểu · Sắp xếp câu · Đóng vai'],['listening','Luyện nghe','Bốn file Q2B10 · Bản ghi BTNC · Tự luyện'],['writing','Luyện viết','Chữ Hán trong bài 10']].map(([id,title,desc])=>'<a class="card card-link" href="#'+id+'"><h3>'+title+' ↗</h3><p>'+desc+'</p></a>').join('')+'</div><article class="card grammar"><h2>Khởi động</h2><p>你去中国人家里吃过饭吗？<br>你喜欢吃什么样的中国菜？<br>说一下你知道的几个中国菜的名字。</p></article>'+lesson10References();}
function lesson10Grammar(){app.innerHTML=intro('MẪU CÂU & ÔN TẬP · BÀI 10','Nói lịch sự khi đến nhà làm khách.','Bài 10 tập trung vào hoạt động và hội thoại; các mẫu dưới đây được rút ra để ôn, không phải mục ngữ pháp mới riêng trong sách.')+'<article class="card grammar"><h2>01 · Chào đón và đáp lời</h2><p lang="zh-CN">欢迎！请进！请坐！<br>给您添麻烦了。<br>别客气，不麻烦。<br>您辛苦了！<br>欢迎再来。</p><p>Hoan nghênh, mời vào, mời ngồi. · Làm phiền cô rồi. · Đừng khách sáo, không phiền đâu. · Cô vất vả rồi! · Lần sau lại đến chơi nhé.</p></article><article class="card grammar"><h2>02 · 别 + động từ</h2><div class="pattern">别 + động từ / cụm động từ</div><p>Khuyên hoặc nhắc ai đừng làm gì.</p><p lang="zh-CN">别客气。<br>上课的时候别吃东西。</p></article><article class="card grammar"><h2>03 · Miêu tả món ăn</h2><div class="pattern">又 + tính từ + 又 + tính từ</div><p lang="zh-CN">糖醋鱼又酸又甜。<br>麻婆豆腐很辣。<br>好吃极了！</p><p>Cá sốt chua ngọt vừa chua vừa ngọt. · Đậu phụ Mapo cay. · Ngon tuyệt!</p></article><article class="card grammar"><h2>04 · Ôn hỏi trải nghiệm và lựa chọn</h2><p lang="zh-CN">你吃过四川菜吗？<br>除了四川菜以外，你还吃过什么菜？<br>你喝茶还是咖啡？<br>你怕不怕辣？<br>喜欢的话，多吃一点儿！</p><p class="sub">过: đã từng · 除了……以外，还……: ngoài… còn… · 还是: lựa chọn trong câu hỏi · 的话: nếu…</p></article><a class="btn" href="#practice">Luyện làm khách →</a>'+lesson10References(3,4);}
let lesson10PracticeMode='vocab';
function gradeLesson10Exercise(mode,index,draft){const q=lesson10Data.exercises[mode][index],variants=[q[1]];if(mode==='choose'&&index===1)variants.push('你昨天几点回家的');return {correct:variants.some(a=>compareHanzi(draft,a).correct),answer:q[1],note:q[2]};}
function lesson10Practice(){app.innerHTML=intro('LUYỆN TẬP · BÀI 10','Đến chơi nhà và giới thiệu món ăn.','Ôn mẫu câu theo ảnh, đọc hiểu và luyện đóng vai chủ nhà – khách.')+'<div class="toolbar lesson2-modes">'+[['vocab','Điền từ'],['reading','Đọc hiểu'],['choose','Sắp xếp câu'],['pictures','Hỏi đáp theo ảnh'],['food','Giới thiệu món ăn'],['shop','Đóng vai làm khách'],['summary','Tự tổng kết']].map(([id,title])=>'<button class="btn '+(lesson10PracticeMode===id?'':'secondary')+'" data-lesson10-mode="'+id+'">'+title+'</button>').join('')+'</div><div id="lesson10ExerciseArea"></div>';document.querySelectorAll('[data-lesson10-mode]').forEach(b=>b.onclick=()=>{lesson10PracticeMode=b.dataset.lesson10Mode;lesson10Practice();});renderLesson10ExerciseArea();}
function renderLesson10ExerciseArea(){const area=document.querySelector('#lesson10ExerciseArea'),mode=lesson10PracticeMode;if(mode==='pictures'){renderLesson10Review(area);return;}if(mode==='food'){renderLesson10Food(area);return;}if(mode==='shop'){renderLesson10Shop(area);return;}if(mode==='summary'){area.innerHTML='<article class="card grammar"><h2>Từ ngữ và mẫu câu muốn nhớ</h2><label for="lesson10SummaryWords">Từ ngữ</label><textarea id="lesson10SummaryWords" rows="4"></textarea><label for="lesson10SummaryPatterns">Mẫu câu</label><textarea id="lesson10SummaryPatterns" rows="4"></textarea><p class="sub">Tự động lưu trong tiến độ Lesson 10.</p></article>'+lesson10References(12,12);for(const[id,key]of [['lesson10SummaryWords','words'],['lesson10SummaryPatterns','patterns']]){document.querySelector('#'+id).value=state.lesson10Summary?.[key]||'';document.querySelector('#'+id).oninput=e=>{state.lesson10Summary=state.lesson10Summary||{};state.lesson10Summary[key]=e.target.value;save();};}return;}
 const saved=state.lesson10Exercises?.[mode]||{};
 area.innerHTML=(mode==='reading'?'<article class="card grammar"><h2>Đoạn đọc</h2><p class="lesson2-reading" lang="zh-CN">'+lesson10Data.reading+'</p><p class="sub">Từ hỗ trợ: 坐地铁 (đi tàu điện ngầm), 口 (lượng từ cho người trong gia đình), 又……又…… (vừa… vừa…).</p></article>':'')+'<form id="lesson10ExerciseForm">'+lesson10Data.exercises[mode].map((q,i)=>'<article class="card grammar"><label for="lesson10Answer'+i+'">'+(i+1)+'. '+esc(q[0])+'</label><input class="lesson2-answer" id="lesson10Answer'+i+'" lang="zh-CN" placeholder="Gõ chữ Hán…" value="'+esc(saved[i]?.draft||'')+'"><div id="lesson10Feedback'+i+'" role="status"></div></article>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson10Result" role="status"></p></form>'+(mode==='reading'?'<h2>Chọn đáp án theo đoạn văn</h2><form id="lesson10ReadingQuiz">'+lesson10Data.exercises.comprehension.map((q,i)=>'<fieldset class="card question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l10reading'+i+'" value="'+j+'"> '+v+'</label>').join('')+'<div id="lesson10ReadingFeedback'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra đọc hiểu</button><p id="lesson10ReadingResult" role="status"></p></form>':'')+lesson10References(mode==='vocab'?2:10,mode==='vocab'?2:11);
 document.querySelector('#lesson10ExerciseForm').onsubmit=e=>{e.preventDefault();const records={};let count=0;lesson10Data.exercises[mode].forEach((q,i)=>{const draft=document.querySelector('#lesson10Answer'+i).value,r=gradeLesson10Exercise(mode,i,draft);records[i]={draft,correct:r.correct};count+=r.correct?1:0;document.querySelector('#lesson10Feedback'+i).innerHTML='<div class="feedback '+(r.correct?'good':'bad')+'">'+(r.correct?'✓ Chính xác':'Đáp án tham khảo: '+esc(r.answer))+'<br>'+esc(r.note)+'</div>';});state.lesson10Exercises=state.lesson10Exercises||{};state.lesson10Exercises[mode]=records;save();document.querySelector('#lesson10Result').textContent='Đúng '+count+' / '+lesson10Data.exercises[mode].length+' câu.';};
 if(mode==='reading')document.querySelector('#lesson10ReadingQuiz').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;lesson10Data.exercises.comprehension.forEach((q,i)=>{const answer=form.get('l10reading'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson10ReadingFeedback'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson10Exercises=state.lesson10Exercises||{};state.lesson10Exercises.comprehension=records;save();document.querySelector('#lesson10ReadingResult').textContent='Đúng '+count+' / '+lesson10Data.exercises.comprehension.length+' câu.';};
}

function lesson10Listening(){const groups=[{"title":"10-1 · Đến nhà cô Hoàng làm khách","d":0,"tf":[["黄老师非常欢迎田中、大卫来她家。","Sai — hội thoại chỉ có田中 đến làm khách, không nhắc 大卫."],["黄老师家又大又漂亮。","Đúng."],["黄老师的爱人不在家，女儿在家。","Sai — chồng và các con đều ra ngoài."],["田中想喝茶。","Sai — em ấy chọn cà phê."]],"questions":[["黄老师家一共几个人？","四个人：黄老师、爱人、女儿和儿子。"],["黄老师的孩子在家吗？","不在，都出去了。"],["田中是上午还是下午去黄老师家的？","根据“孩子中午有约会”，可推测是上午；课文没有直接说明到访时间。"],["黄老师家几个人工作了？","四个人：黄老师、爱人和两个孩子。"]]},{"title":"10-2 · Thưởng thức bữa cơm","d":1,"questions":[["辣的菜叫什么名字？","麻婆豆腐。"],["糖醋鱼味道怎么样？","又酸又甜。"],["田中吃过糖醋鱼吗？","课文没有直接说明以前吃没吃过；他这次尝了并问菜名。"],["田中怕不怕辣？","不怕。"]]}];app.innerHTML=intro('LUYỆN NGHE · BÀI 10','Đến nhà làm khách và thưởng thức bữa cơm.','Bốn file Q2B10 bạn cung cấp, kèm bản ghi BTNC và câu tự luyện.')+'<div class="notice">Các file Q2B10 thuộc bộ BTNC. NC1–NC3 được đối chiếu với PDF bài 10. Chưa xác nhận bản thu tương ứng mã 10-1, 10-2, 10-3 trong giáo trình.</div>'+['Q2B10.mp3','Q2B10.NC1.MP3','Q2B10.NC2.MP3','Q2B10.NC3.MP3'].map((file,i)=>'<article class="card grammar"><h3>'+file+'</h3><audio controls preload="none" src="audio/'+file+'"></audio><label>Tốc độ <select data-lesson10-audio="'+i+'" aria-label="Tốc độ '+file+'"><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option></select></label>'+lesson10BTNCMarkup(file)+'</article>').join('')+'<h2>Luyện thêm theo văn bản giáo trình</h2>'+lesson2VoiceControls()+groups.map(g=>'<article class="card grammar"><h2>'+g.title+'</h2><button class="btn secondary" data-lesson10-listen="'+g.d+'">▶ Nghe toàn hội thoại bằng giọng thiết bị</button>'+(g.tf?'<h3>Đúng / sai</h3>'+g.tf.map(([q,a])=>'<details class="lesson2-answer-key"><summary>'+q+'</summary><p>'+a+'</p></details>').join(''):'')+'<h3>Nghe và trả lời</h3>'+g.questions.map(([q,a])=>'<details class="lesson2-answer-key"><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'<p class="sub">Đáp án theo văn bản hội thoại, không phải theo audio BTNC. Một số câu sách không có đủ thông tin trực tiếp trong văn bản; phần trả lời nêu rõ điều đó.</p></article>').join('')+'<article class="card grammar"><h2>10-3 · Bài nghe mở rộng</h2><p class="notice">Chưa xác nhận bản thu tương ứng 10-3 nên phần này chưa chấm điểm.</p><h3>Đúng / sai</h3><ol><li>这个饭店的糖醋鱼很有名。</li><li>这个饭店的牛肉很辣。</li><li>男的要了一碗米饭。</li><li>男的没有要喝的。</li></ol><h3>Chọn đáp án</h3><ol><li>饭店的人建议男的吃什么？<br>A. 牛肉　B. 茶　C. 糖醋鱼</li><li>男的不喜欢什么味道的菜？<br>A. 辣的　B. 甜的　C. 酸的</li><li>男的要了几个菜？<br>A. 两个　B. 三个　C. 四个</li><li>男的喝什么？<br>A. 一杯可乐　B. 一瓶可乐　C. 一杯茶</li></ol></article>'+lesson10References(9,10);bindLesson10BTNC();document.querySelectorAll('[data-lesson10-audio]').forEach(s=>s.onchange=()=>document.querySelectorAll('audio')[Number(s.dataset.lesson10Audio)].playbackRate=Number(s.value));document.querySelectorAll('audio').forEach(a=>a.onplay=()=>{stopWordAudio();document.querySelectorAll('audio').forEach(b=>{if(a!==b)b.pause();});});bindLesson2Voice(lesson10Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelectorAll('[data-lesson10-listen]').forEach(b=>b.onclick=()=>lesson2Speak(lesson10Data.dialogues[Number(b.dataset.lesson10Listen)][1].map(l=>l[1]).join(' ')));}
function renderLesson10Shop(area){const saved=state.lesson10Visit||{};area.innerHTML='<article class="card grammar"><h2>Đóng vai chủ nhà – hai người khách</h2><p>Ba người luyện từ lúc gõ cửa, chào đón, mời uống nước đến bữa cơm và chào ra về. Điền tên món và loại đồ uống để tạo lời thoại tham khảo.</p>'+[['host','Chủ nhà','王老师'],['guest1','Khách thứ nhất','田中'],['guest2','Khách thứ hai','卡玛拉'],['drink','Đồ uống','茶'],['dish','Món ăn','糖醋鱼'],['flavour','Vị món ăn','又酸又甜']].map(([key,label,hint])=>'<label for="lesson10Visit'+key+'">'+label+'</label><input class="lesson2-answer" id="lesson10Visit'+key+'" data-lesson10-visit="'+key+'" placeholder="'+hint+'" value="'+esc(saved[key]||'')+'">').join('')+'<button class="btn" id="lesson10VisitMake">Tạo hội thoại tham khảo</button><p id="lesson10VisitOutput" style="white-space:pre-line;line-height:2"></p></article>'+lesson10References(9,9);document.querySelectorAll('[data-lesson10-visit]').forEach(input=>input.oninput=e=>{state.lesson10Visit=state.lesson10Visit||{};state.lesson10Visit[input.dataset.lesson10Visit]=e.target.value;save();});document.querySelector('#lesson10VisitMake').onclick=()=>document.querySelector('#lesson10VisitOutput').textContent=lesson10VisitDialogue(state.lesson10Visit||{});}
for(const[route,handler]of Object.entries({home:lesson10Home,grammar:lesson10Grammar,dialogue:lesson10Dialogue,practice:lesson10Practice,listening:lesson10Listening}))pages[route]=function(){if(state.lesson==='10')handler();else lesson10PreviousPages[route]();};
pages.writing=function(){lesson10PreviousPages.writing();if(state.lesson!=='10')return;document.querySelector('#app .eyebrow').textContent='LUYỆN VIẾT · BÀI 10';const chars=[...new Set(lesson10Data.rows.map(r=>r[0]).join('').split('').filter(c=>/[\u3400-\u9fff]/.test(c)))];document.querySelector('#model').innerHTML=chars.map(c=>'<option>'+c+'</option>').join('');document.querySelector('#modelchar').textContent=chars[0];};
const lesson10ReviewTasks=[['吃四川菜','你吃过四川菜吗','我吃过四川菜','我还吃过上海菜'],['见爱人','你见过我的爱人吗','我见过你的爱人','我还见过你的孩子'],['看英语书','你看过英语书吗','我看过英语书','我还看过汉语书'],['给黄老师打电话','你给黄老师打过电话吗','我给黄老师打过电话','我还给马老师打过电话'],['买衣服','你买过衣服吗','我买过衣服','我还买过鞋'],['参加篮球比赛','你参加过篮球比赛吗','我参加过篮球比赛','我还参加过网球比赛']];
function gradeLesson10Review(i,j,draft){const t=lesson10ReviewTasks[i],variants=[t[j+1]];if(j===1)variants.push(i===3?'打过':i===0?'吃过':i===1?'见过':i===2?'看过':i===4?'买过':'参加过');return variants.some(a=>compareHanzi(draft,a).correct);}
function renderLesson10Review(area){const saved=state.lesson10Exercises?.review||{};area.innerHTML='<article class="card grammar"><h2>Ôn hỏi đáp theo ảnh</h2><p>Hỏi đã từng làm gì, trả lời khẳng định rồi bổ sung một trải nghiệm theo cặp ảnh. Đây là mẫu luyện theo gợi ý, không phải trải nghiệm bắt buộc của bạn. Thời gian có thể tự bổ sung khi luyện nói.</p><div class="grid">'+[3,4].map(i=>'<img loading="lazy" src="images/lesson10/source-'+i+'.png" alt="Bài ôn theo ảnh trang '+lesson10SourcePages[i-1]+'" style="width:440px;max-width:100%">').join('')+'</div>'+lesson10ReviewTasks.map((t,i)=>'<h3>'+(i+1)+'. '+t[0]+'</h3>'+['Câu hỏi: đã từng… chưa?','Trả lời: đã từng','Thêm trải nghiệm theo ảnh thứ hai'].map((q,j)=>'<label for="lesson10Review'+i+'-'+j+'">'+q+'</label><input class="lesson2-answer" lang="zh-CN" id="lesson10Review'+i+'-'+j+'" value="'+esc(saved[i]?.drafts?.[j]||'')+'"><p id="lesson10ReviewFeedback'+i+'-'+j+'" role="status"></p>').join('')+'<button class="btn secondary" data-lesson10-review="'+i+'">Kiểm tra</button>').join('')+'</article>';document.querySelectorAll('[data-lesson10-review]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.lesson10Review),drafts=[],results=[];for(let j=0;j<3;j++){const draft=document.querySelector('#lesson10Review'+i+'-'+j).value,correct=gradeLesson10Review(i,j,draft);drafts.push(draft);results.push(correct);document.querySelector('#lesson10ReviewFeedback'+i+'-'+j).textContent=correct?'✓ Chính xác':'Mẫu tham khảo: '+lesson10ReviewTasks[i][j+1]+'。';}state.lesson10Exercises=state.lesson10Exercises||{};state.lesson10Exercises.review=state.lesson10Exercises.review||{};state.lesson10Exercises.review[i]={drafts,results};save();});}
function lesson10FoodReport(p){return (p.name||'糖醋鱼')+'的味道'+(p.flavour||'又酸又甜')+'，'+(p.comment||'好吃极了')+'。';}
function renderLesson10Food(area){const saved=state.lesson10Food||{};area.innerHTML='<article class="card grammar"><h2>Giới thiệu món Trung bạn biết</h2><p>Hoạt động nhóm: kể tên món và đặc điểm, rồi cử một bạn trình bày. Gợi ý trong sách: 麻婆豆腐很辣；糖醋鱼又酸又甜. Câu trả lời mở.</p>'+[['name','Tên món','糖醋鱼'],['flavour','Vị','又酸又甜'],['comment','Nhận xét','好吃极了']].map(([key,label,hint])=>'<label for="lesson10Food'+key+'">'+label+'</label><input class="lesson2-answer" id="lesson10Food'+key+'" data-lesson10-food="'+key+'" placeholder="'+hint+'" value="'+esc(saved[key]||'')+'">').join('')+'<button class="btn" id="lesson10FoodMake">Tạo lời giới thiệu</button><p id="lesson10FoodOutput"></p></article>'+lesson10References(8,8);document.querySelectorAll('[data-lesson10-food]').forEach(input=>input.oninput=e=>{state.lesson10Food=state.lesson10Food||{};state.lesson10Food[input.dataset.lesson10Food]=e.target.value;save();});document.querySelector('#lesson10FoodMake').onclick=()=>document.querySelector('#lesson10FoodOutput').textContent=lesson10FoodReport(state.lesson10Food||{});}
function lesson10VisitDialogue(p){const h=p.host||'王老师',a=p.guest1||'田中',b=p.guest2||'卡玛拉',drink=p.drink||'茶',dish=p.dish||'糖醋鱼',flavour=p.flavour||'又酸又甜';return '（敲门）\n'+h+'：谁啊？\n'+a+'：是我们，'+a+'和'+b+'。\n'+h+'：欢迎！请进！请坐！喝点儿'+drink+'吧。\n'+b+'：给您添麻烦了。\n'+h+'：别客气，不麻烦。我们吃饭吧！\n'+a+'：做了这么多菜，您辛苦了！这个菜叫什么？\n'+h+'：这是'+dish+'。\n'+b+'：味道'+flavour+'，好吃极了！\n'+h+'：喜欢的话，多吃一点儿！\n'+a+'：今天给您添麻烦了！\n'+h+'：欢迎再来。';}
render();
